```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_read};

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch. The result is deliberately discarded so the
        // node's output is unchanged; transport failures are returned as
        // values by `fetch` and ignored.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let urls = match state_read::get("subscriptions") {
            Some(raw) => raw
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

Notes:
- `RunInfo` has no field called text, so I used `info.date` as the input text for the `q=` parameter, percent-encoded.
- The enrichment result is discarded, so the output is the same as before.
- I assumed the state key is `subscriptions`, holding newline-separated URLs. A missing key yields an empty list, so `urls` is always present.

